def solve(strings):
    if not strings:
        return 0
    if len(strings) == 1:
        return len(strings[0])

    # Find the shortest string to limit comparison scope
    min_len = min(len(s) for s in strings)

    # Compare characters at each position across all strings
    for i in range(min_len):
        char = strings[0][i]
        for s in strings[1:]:
            if s[i] != char:
                return i
    return min_len

