def solve(strings):
    if not strings:
        return ""
    # Start with the first string as the candidate prefix
    prefix = strings[0]

    for s in strings[1:]:
        # Reduce the prefix until it matches the start of the current string
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

